function currentUser(){return (store.data.users||[]).find(u=>u.id===store.data.session?.userId)||{};}
function operatorRole(){return ['OPERADOR_BODEGA','OPERADOR_RECEPCION'].includes(effectiveRole(currentUser(),siteId()));}
function operatorOnly(){return operatorRole()&&!perms().manage;}
function locationModule(loc){const raw=loc?.module??String(loc?.id||loc?.label||'').match(/-M(\d+)/i)?.[1]??'';return String(raw||'');}
function moduleLabel(value){return value?`Módulo ${value}`:'Sin módulo';}
function siteId(){return activeSiteId(store.data);}
function perms(){return inventoryPermissionsForUser(currentUser(),siteId());}
function mapPerms(){return mapPermissionsForUser(currentUser(),siteId());}
function palletPerms(){return palletPermissionsForUser(currentUser(),siteId());}
function stockPerms(){return codePermissionsForUser(currentUser(),siteId());}
function sessions(){store.data.planning=store.data.planning||{};store.data.planning.inventorySessions=store.data.planning.inventorySessions||[];return store.data.planning.inventorySessions;}
function siteName(id){return (store.data.sites||[]).find(s=>s.id===id)?.name||id;}
function userName(id){return (store.data.users||[]).find(u=>u.id===id)?.name||id||'—';}
function fecha(v){return v?new Date(v).toLocaleString('es-CL'):'—';}
function productName(code){const p=(store.data.products||[]).find(x=>String(x.code)===String(code));return p?.name||p?.description||`Producto ${code}`;}
function activeRacks(sid=siteId()){return (store.data.racks||[]).filter(r=>r.siteId===sid&&r.status!=='INACTIVO').sort((a,b)=>String(a.name||a.id).localeCompare(String(b.name||b.id),undefined,{numeric:true}));}
const REC_MAP_LAYOUT={R1:{x:3,y:13,w:4,h:72},R2:{x:16,y:13,w:4,h:42},R3:{x:20,y:13,w:4,h:42},R4:{x:31,y:13,w:4,h:42},R5:{x:35,y:13,w:4,h:42},R6:{x:44,y:13,w:4,h:42},R7:{x:3,y:2,w:44,h:6},R8:{x:16,y:70,w:4,h:18},R9:{x:31,y:57,w:8,h:6},R10:{x:71,y:36,w:4,h:42},R11:{x:75,y:36,w:4,h:42},R12:{x:84,y:36,w:4,h:42},R13:{x:88,y:36,w:4,h:42}};
function rackMapKey(r){return String(r?.rackCode||r?.id||'').match(/R\d+/i)?.[0]?.toUpperCase()||String(r?.id||'').toUpperCase();}
function inventoryMapLayout(racks=activeRacks()){const saved=store.data.settings?.map3dLayouts?.[siteId()]||{},out={};racks.forEach((r,i)=>{const key=rackMapKey(r),base=siteId()==='REC'&&REC_MAP_LAYOUT[key]?REC_MAP_LAYOUT[key]:{x:4+(i%5)*19,y:8+Math.floor(i/5)*27,w:6,h:20};out[r.id]={...(base||{}),...(saved[key]||{})};});return out;}
function rackMapReference(){const racks=activeRacks(),layout=inventoryMapLayout(racks);return `<section class="inventory-map-reference"><div class="inventory-map-reference-head"><div><b>Mapa de referencia</b><small>Ubica visualmente cada rack antes de asignarlo.</small></div><a class="ghost" href="#/mapa3d" target="_blank" rel="noopener">Abrir mapa completo</a></div><div class="inventory-mini-map">${racks.map(r=>{const slot=layout[r.id]||{x:5,y:5,w:6,h:20};return `<button type="button" class="inventory-mini-rack" data-map-rack="${esc(r.id)}" style="left:${Number(slot.x)||0}%;top:${Number(slot.y)||0}%;width:${Math.max(3,Number(slot.w)||5)}%;height:${Math.max(5,Number(slot.h)||18)}%"><b>${esc(r.name||rackMapKey(r))}</b></button>`;}).join('')}</div><small class="inventory-map-reference-note">Toca un rack del mapa para ir directamente a su asignación. El plano refleja la distribución guardada en Mapa 3D.</small></section>`;}
function sectorName(id){return (store.data.sectors||[]).find(s=>s.id===id)?.name||'Zona sin nombre';}
function rackName(id){return (store.data.racks||[]).find(r=>r.id===id)?.name||id;}
function rackForLocation(locationId){return (store.data.locations||[]).find(l=>l.id===locationId)?.rackId||'';}
function taskForUser(s,userId=currentUser().id){return (s.assignments||[]).find(a=>a.userId===userId)||null;}
function assignedRackIds(s,userId=currentUser().id){return new Set(taskForUser(s,userId)?.rackIds||[]);}
function locationByInput(value){const clean=String(value||'').trim().toUpperCase();if(!clean)return null;return (store.data.locations||[]).find(l=>l.siteId===siteId()&&l.active!==false&&[l.id,l.scanCode,l.label].some(v=>String(v||'').trim().toUpperCase()===clean))||null;}
function palletByInput(value){const clean=String(value||'').trim().toUpperCase();if(!clean)return null;return (store.data.pallets||[]).find(p=>p.siteId===siteId()&&[p.id,p.physicalCode,p.displayName].some(v=>String(v||'').trim().toUpperCase()===clean))||null;}
function sessionCompanyId(s){return s.companyId||siteCompanyId((store.data.sites||[]).find(x=>x.id===s.siteId),store.data);}
function canSeeSession(s){const p=perms(),u=currentUser(),mine=!!taskForUser(s,u.id);return sessionCompanyId(s)===activeCompanyId(store.data)&&s.siteId===siteId()&&(p.manage||p.review||mine);}
function isGlobalInventoryAdmin(){return currentUser()?.role==='ADMIN_GLOBAL';}
function visibleSessions(){return sessions().filter(canSeeSession).filter(s=>isGlobalInventoryAdmin()||!s.managerArchivedAt).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));}
function inventorySessionSearchText(s){return [s.number,s.id,s.name,siteName(s.siteId),STATUS_LABEL[s.status]||s.status,TYPE_LABEL[sessionMode(s)],PURPOSE_LABEL[sessionPurpose(s)],SCOPE_LABEL[s.scope||'ALL_ACTIVE_RACKS'],...(s.assignments||[]).flatMap(a=>[userName(a.userId),...(a.rackIds||[]).map(rackName)]),s.createdAt,s.closedAt,s.managerArchivedAt].filter(Boolean).join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function inventoryListMatches(s){const q=inventoryListQuery.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(),date=String(s.createdAt||'').slice(0,10);return (!q||inventorySessionSearchText(s).includes(q))&&(inventoryListStatus==='ALL'||inventoryListStatus==='ARCHIVED'&&!!s.managerArchivedAt||inventoryListStatus===s.status)&&(inventoryListUser==='ALL'||(s.assignments||[]).some(a=>a.userId===inventoryListUser))&&(inventoryListPurpose==='ALL'||sessionPurpose(s)===inventoryListPurpose)&&(inventoryListScope==='ALL'||(s.scope||'ALL_ACTIVE_RACKS')===inventoryListScope)&&(!inventoryListFrom||date>=inventoryListFrom)&&(!inventoryListTo||date<=inventoryListTo);}
function inventoryListFilters(list){const users=[...new Set(list.flatMap(s=>(s.assignments||[]).map(a=>a.userId)))].filter(Boolean).sort((a,b)=>userName(a).localeCompare(userName(b)));return `<section class="inventory-list-filters"><div class="inventory-filter-search"><label><span>Buscar</span><input id="inventory-list-search" value="${esc(inventoryListQuery)}" placeholder="Número, nombre, responsable, rack…" autocomplete="off"></label></div><label><span>Estado</span><select id="inventory-list-status"><option value="ALL">Todos</option><option value="EN_CONTEO">En conteo</option><option value="EN_REVISION">En revisión</option><option value="CERRADA">Cerrados</option><option value="CONCILIADA">Conciliados</option>${isGlobalInventoryAdmin()?'<option value="ARCHIVED">Archivados</option>':''}</select></label><label><span>Responsable</span><select id="inventory-list-user"><option value="ALL">Todos</option>${users.map(id=>`<option value="${esc(id)}">${esc(userName(id))}</option>`).join('')}</select></label><label><span>Tipo</span><select id="inventory-list-purpose"><option value="ALL">Todos</option><option value="GENERAL">General</option><option value="CICLICO">Cíclico</option><option value="RECONTEO">Reconteo</option></select></label><label><span>Alcance</span><select id="inventory-list-scope"><option value="ALL">Todos</option><option value="ALL_ACTIVE_RACKS">Toda la bodega</option><option value="SELECTED_RACKS">Parcial / racks</option></select></label><label><span>Desde</span><input id="inventory-list-from" type="date" value="${esc(inventoryListFrom)}"></label><label><span>Hasta</span><input id="inventory-list-to" type="date" value="${esc(inventoryListTo)}"></label><button id="inventory-list-clear" class="ghost" type="button">Limpiar filtros</button></section><div id="inventory-filter-count" class="inventory-filter-count"></div>`;}
function nextNumber(){const today=new Date().toISOString().slice(0,10).replaceAll('-','');const prefix=`INV-${today}-`;const n=sessions().filter(s=>String(s.number||s.id||'').startsWith(prefix)).length+1;return `${prefix}${String(n).padStart(3,'0')}`;}
function authorizedCounters(){const sid=siteId();return (store.data.users||[]).filter(u=>{if(u.active===false||['PAUSED','DISABLED','DELETED'].includes(u.accessStatus))return false;const assignments=Array.isArray(u.accessAssignments)?u.accessAssignments:[],siteIds=Array.isArray(u.siteIds)?u.siteIds:[],hasScopedAccess=assignments.length>0||siteIds.length>0,hasSiteAccess=!hasScopedAccess||assignments.some(a=>a?.siteId===sid)||siteIds.includes(sid);return hasSiteAccess&&['OPERADOR_BODEGA','OPERADOR_RECEPCION'].includes(effectiveRole(u,sid));});}
function validateCounterAssignments(byUser){const allowed=new Set(authorizedCounters().map(u=>u.id)),invalid=[...byUser.keys()].filter(id=>!allowed.has(id));if(invalid.length)throw new Error(`Solo puedes asignar racks a operarios activos del centro: ${invalid.map(userName).join(', ')}.`);}
function physicalByProductAtSite(){const locSite=new Map((store.data.locations||[]).map(l=>[l.id,l.siteId])),palSite=new Map((store.data.pallets||[]).map(p=>[p.id,p.siteId])),out={};for(const row of store.data.inventory||[]){const sid=row.siteId||locSite.get(row.locationId)||palSite.get(row.palletId);if(sid!==siteId())continue;const q=Number(row.qty||0);if(q<=0)continue;out[row.productCode]=(out[row.productCode]||0)+q;}return out;}
function physicalByProductForSession(s){const allowedRacks=new Set(sessionRackIds(s)),locations=new Map((store.data.locations||[]).filter(l=>l.siteId===s.siteId).map(l=>[l.id,l])),pallets=new Map((store.data.pallets||[]).filter(p=>p.siteId===s.siteId).map(p=>[p.id,p])),out={};for(const row of store.data.inventory||[]){const pallet=row.palletId?pallets.get(row.palletId):null,location=locations.get(row.locationId||pallet?.locationId),sid=row.siteId||location?.siteId||pallet?.siteId;if(sid!==s.siteId||!location||!allowedRacks.has(location.rackId))continue;const q=Number(row.qty||0);if(q<=0)continue;out[row.productCode]=(out[row.productCode]||0)+q;}return out;}
function countedSummary(s){const out=new Map();for(const line of s.lines||[]){const prev=out.get(line.productCode)||{code:line.productCode,name:line.productName||productName(line.productCode),counted:0,positions:new Set()};prev.counted+=Number(line.qty||0);prev.positions.add(`${line.locationId}@@${line.palletId||''}`);out.set(line.productCode,prev);}return [...out.values()].map(x=>({...x,positions:x.positions.size}));}
function consolidatedCountRows(s){const out=new Map();for(const line of s.lines||[]){const code=String(line.productCode||''),prev=out.get(code)||{code,name:line.productName||productName(code),qty:0,positions:new Set(),racks:new Set(),operators:new Set(),lines:[]};prev.qty+=Number(line.qty||0);prev.positions.add(`${line.locationId||''}@@${line.palletId||''}`);if(line.rackId)prev.racks.add(line.rackId);if(line.countedBy)prev.operators.add(line.countedBy);prev.lines.push(line);out.set(code,prev);}return [...out.values()].map(r=>({...r,positionCount:r.positions.size,rackIds:[...r.racks],operatorIds:[...r.operators]})).sort((a,b)=>String(a.code).localeCompare(String(b.code),undefined,{numeric:true}));}
function consolidatedCountHtml(s){const rows=consolidatedCountRows(s),units=rows.reduce((n,r)=>n+r.qty,0),operators=new Set((s.lines||[]).map(l=>l.countedBy).filter(Boolean)),positions=new Set((s.lines||[]).map(l=>`${l.locationId||''}@@${l.palletId||''}`));return `<section class="inventory-manager-assignments inventory-live-dashboard"><div class="panel-head inventory-manager-head"><div><span class="eyebrow">RESULTADO CONSOLIDADO EN VIVO</span><h3>Conteo físico unificado</h3><small>Suma automáticamente el mismo SKU aunque haya sido contado por distintos operarios, racks o posiciones. No modifica stock ni realiza conciliación.</small></div><button id="inventory-export-consolidated" class="secondary" type="button" ${rows.length?'':'disabled'}>Descargar consolidado Excel</button></div><div class="inventory-live-kpis"><div><small>SKU distintos</small><b>${rows.length}</b></div><div><small>Unidades físicas</small><b>${units}</b></div><div><small>Operarios con registros</small><b>${operators.size}</b></div><div><small>Posiciones con registros</small><b>${positions.size}</b></div></div>${rows.length?`<div class="inventory-rack-live-grid">${rows.map(r=>`<details class="inventory-rack-live-card"><summary><span><b>${esc(r.code)}</b><small>${esc(r.name)} · ${r.positionCount} posición(es) · ${r.operatorIds.length} operario(s)</small></span><strong>${r.qty} un.</strong></summary><div class="inventory-rack-live-body"><div class="inventory-manager-detail-list">${r.lines.slice().sort((a,b)=>String(a.rackId||'').localeCompare(String(b.rackId||''),undefined,{numeric:true})||String(a.locationId||'').localeCompare(String(b.locationId||''),undefined,{numeric:true})).map(l=>`<div class="inventory-manager-detail-row"><span><b>${esc(l.productCode)}</b><small>${esc(l.productName||productName(l.productCode))}</small></span><span>${esc(rackName(l.rackId))}</span><span>${esc(l.locationLabel||l.locationId||'—')}</span><span>${esc(l.palletLabel||l.palletId||'—')}</span><strong>${Number(l.qty||0)}</strong><small>${esc(userName(l.countedBy))} · ${esc(fecha(l.countedAt))}</small></div>`).join('')}</div></div></details>`).join('')}</div>`:empty('Aún no hay conteos registrados','El consolidado aparecerá automáticamente a medida que los operarios guarden cantidades.')}</section>`;}
function taskStatus(s,a){if(a.status)return a.status;if((s.lines||[]).some(l=>l.assignmentId===a.id||a.rackIds?.includes(l.rackId)))return 'EN_CONTEO';return 'PENDIENTE';}
function allTasksSubmitted(s){return (s.assignments||[]).length>0&&(s.assignments||[]).every(a=>taskStatus(s,a)==='ENVIADO_REVISION');}
function hasInventoryActivity(s){return (s.lines||[]).length>0||(s.assignments||[]).some(a=>a.startedAt||a.submittedAt||(a.completedRackIds||[]).length||(['EN_CONTEO','ENVIADO_REVISION'].includes(a.status)));}
function canDeleteSession(s){return !!perms().manage&&s.status==='EN_CONTEO'&&!hasInventoryActivity(s);}
function canGlobalDeleteInventory(s){return isGlobalInventoryAdmin()&&s.status!=='CONCILIADA';}
function reviewOverrideQty(s,code,rawPhysical){const v=s.reviewOverridesByProduct?.[String(code)];return Number.isFinite(Number(v))?Number(v):Number(rawPhysical||0);}
function correctionHistoryFor(s,code){return (s.reviewCorrectionHistory||[]).filter(x=>String(x.productCode)===String(code));}

function rackLocations(rackId){return (store.data.locations||[]).filter(l=>l.siteId===siteId()&&l.active!==false&&l.rackId===rackId).sort((a,b)=>String(a.id).localeCompare(String(b.id),undefined,{numeric:true}));}
function palletAtLocation(locationId){return (store.data.pallets||[]).find(p=>p.siteId===siteId()&&p.locationId===locationId&&p.status!=='CERRADO')||null;}
function locationStockRows(locationId){return (store.data.inventory||[]).filter(i=>i.locationId===locationId&&Number(i.qty||0)>0);}
function locationWasReset(s,locationId){return new Set(s?.resetLocationIds||[]).has(locationId);}
function locationNeedsReset(locationId){return locationStockRows(locationId).length>0||(store.data.pallets||[]).some(p=>p.siteId===siteId()&&p.locationId===locationId&&p.status!=='CERRADO');}
function locationWorkLabel(location){return location?.label||location?.scanCode||location?.id||'Posición';}
function positionWorkValue(location){const pallet=palletAtLocation(location?.id);return pallet?.id||location?.id||'';}
function rackWorkMap(s,task){if(!mapPerms().view)return `<div class="inventory-map-permission-note"><b>Mapa no habilitado</b><small>El administrador puede activar “Ver mapa 3D y estructura operativa” en Usuarios.</small></div>`;const assigned=new Set(task?.rackIds||sessionRackIds(s)),racks=activeRacks(s.siteId),layout=inventoryMapLayout(racks);return `<section class="inventory-work-map"><div class="inventory-work-map-head"><div><span class="eyebrow">ORIENTACIÓN</span><h3>Elige el rack en el mapa</h3><small>Toca un rack asignado para trabajar sus posiciones.</small></div><a class="ghost" href="#/mapa3d?inventory=${encodeURIComponent(s.id)}">Abrir mapa 3D</a></div><div class="inventory-work-map-stage">${racks.map(r=>{const slot=layout[r.id]||{x:5,y:5,w:6,h:20},enabled=assigned.has(r.id),selected=inventoryWorkRackId===r.id;return `<button type="button" class="inventory-work-map-rack ${enabled?'assigned':'disabled'} ${selected?'selected':''}" data-work-rack="${esc(r.id)}" style="left:${Number(slot.x)||0}%;top:${Number(slot.y)||0}%;width:${Math.max(3,Number(slot.w)||5)}%;height:${Math.max(5,Number(slot.h)||18)}%" ${enabled?'':'disabled'}><b>${esc(r.name||rackMapKey(r))}</b></button>`;}).join('')}</div><div class="inventory-work-rack-chips">${[...assigned].map(id=>`<button type="button" class="${inventoryWorkRackId===id?'primary':'ghost'}" data-work-rack="${esc(id)}">${esc(rackName(id))}</button>`).join('')}</div></section>`;}
function rackWorkPositions(s,task){const allowed=new Set(task?.rackIds||[]);if(!inventoryWorkRackId||!allowed.has(inventoryWorkRackId))return `<section class="inventory-work-empty"><b>Selecciona un rack</b><small>Elige tu rack asignado para comenzar.</small></section>`;const locations=rackLocations(inventoryWorkRackId);if(!locations.length)return `<section class="inventory-work-empty"><b>${esc(rackName(inventoryWorkRackId))} sin posiciones configuradas</b><small>La estructura del rack debe tener ubicaciones activas.</small></section>`;const modules=[...new Set(locations.map(locationModule))].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true}));if(!inventoryWorkModule||!modules.includes(inventoryWorkModule))inventoryWorkModule=modules[0]||'';const visible=locations.filter(l=>locationModule(l)===inventoryWorkModule);return `<section class="inventory-work-positions"><div class="inventory-work-position-head"><div><span class="eyebrow">${esc(rackName(inventoryWorkRackId))}</span><h3>¿Dónde estás?</h3><small>Elige módulo y posición. No necesitas revisar el stock antiguo.</small></div></div><div class="inventory-module-tabs">${modules.map(m=>`<button type="button" class="${inventoryWorkModule===m?'primary':'ghost'} inventory-work-module" data-module="${esc(m)}">${esc(moduleLabel(m))}</button>`).join('')}</div><div class="inventory-position-cards">${visible.map(loc=>{const pal=palletAtLocation(loc.id),selected=inventoryWorkLocationId===loc.id;return `<article class="inventory-position-card ${selected?'selected':''}"><div class="inventory-position-primary"><div><b>${esc(locationWorkLabel(loc))}</b><small>${pal?`Pallet registrado: ${esc(palletDisplayName(pal))}`:'Sin pallet registrado'}</small></div><button class="${selected?'primary':'secondary'} inventory-work-position" type="button" data-location="${esc(loc.id)}">${selected?'✓ Aquí':'Trabajar aquí'}</button></div><div class="inventory-position-detail-switch"><button type="button" class="inventory-position-more ghost" aria-expanded="false">Mostrar detalles</button><div class="inventory-position-details" hidden><span><small>CÓDIGO</small><b>${esc(loc.id)}</b></span><span><small>NIVEL</small><b>${esc(loc.level??'—')}</b></span><span><small>POSICIÓN</small><b>${esc(loc.position||loc.slot||String(loc.id).match(/-(A|B)$/i)?.[1]||'—')}</b></span><span><small>PALLET</small><b>${esc(pal?.physicalCode||pal?.id||'Sin pallet')}</b></span></div></div></article>`;}).join('')}</div></section>`;}
function selectedWorkPositionPanel(s){if(!inventoryWorkLocationId)return '';const loc=(store.data.locations||[]).find(l=>l.id===inventoryWorkLocationId&&l.siteId===siteId()),pal=loc?palletAtLocation(loc.id):null,pp=palletPerms();if(!loc)return '';const prepared=locationWasReset(s,loc.id),needsReset=locationNeedsReset(loc.id)&&!prepared,canReset=stockPerms().physicalStock&&pp.operate;const moveOptions=(store.data.pallets||[]).filter(p=>p.siteId===siteId()&&p.id!==pal?.id&&p.status!=='CERRADO'&&!p.locationId).sort((a,b)=>palletDisplayName(a).localeCompare(palletDisplayName(b),undefined,{numeric:true})).map(p=>`<option value="${esc(p.id)}">${esc(palletDisplayName(p))}</option>`).join('');return `<section class="inventory-position-workbench"><div class="inventory-position-workbench-head"><div><span class="eyebrow">POSICIÓN ACTIVA</span><h3>${esc(locationWorkLabel(loc))}</h3><small>${prepared?'Lista para levantar desde cero.':pal?`Tiene un pallet registrado. No necesitas confiar en su stock anterior.`:'Sin pallet registrado.'}</small></div>${prepared?'<span class="inventory-prepared-badge">✓ PREPARADA</span>':''}</div>${needsReset?`<div class="inventory-reset-position"><div><b>¿Quieres levantar esta posición desde cero?</b><small>Se quitarán solo las cantidades registradas aquí y el pallet anterior quedará libre para reorganizar. Los SKU, nombres, códigos y el pallet no se borran.</small></div>${canReset?'<button id="inventory-reset-position" class="danger-soft" type="button">Preparar posición desde cero</button>':'<small>Necesitas permiso de stock físico y movimiento de pallets.</small>'}</div>`:''}<div class="inventory-position-actions">${!needsReset&&!pal&&pp.register&&pp.operate?`<button id="inventory-create-pallet-here" class="primary" type="button">+ Crear pallet aquí</button>`:''}${!needsReset&&pp.operate&&moveOptions?`<details class="inventory-inline-tool"><summary>Mover pallet existente</summary><div class="inventory-move-pallet-inline"><select id="inventory-move-pallet-select"><option value="">Seleccionar pallet libre…</option>${moveOptions}</select><button id="inventory-move-pallet-here" class="secondary" type="button">Mover aquí</button></div></details>`:''}</div></section>`;}
function inventorySimpleWorkbench(s,task,readOnly){
 const loc=(store.data.locations||[]).find(l=>l.id===inventoryWorkLocationId&&l.siteId===siteId());
 return `<section class="inventory-operator-workbench operator-simple"><details class="operator-position-selector" ${loc?'':'open'}><summary><span><small>1 · UBICACIÓN DE TRABAJO</small><b>${loc?`${esc(rackName(loc.rackId))} · ${esc(locationWorkLabel(loc))}`:'Escanea la etiqueta de ubicación'}</b></span><strong>${loc?'Cambiar':'Comenzar'}</strong></summary><div class="operator-position-options"><button id="inventory-work-scan" class="primary inventory-location-camera" type="button">▣ Escanear ubicación</button><div class="inventory-location-entry"><label for="inventory-work-code">O escribe el código de la etiqueta</label><div><input id="inventory-work-code" autocomplete="off" placeholder="Ej. REC-R2-M1-N1"><button id="inventory-work-use" class="secondary" type="button">Usar ubicación</button></div><small id="inventory-work-status" role="status">Escanea una posición para comenzar, o un rack para elegir su posición.</small></div><details class="operator-manual-location operator-extra" ${inventoryManualLocationOpen?'open':''}><summary>Elegir manualmente · rack, módulo y posición</summary><div><div class="inventory-work-rack-chips">${(task.rackIds||[]).map(id=>`<button type="button" class="${inventoryWorkRackId===id?'primary':'ghost'}" data-work-rack="${esc(id)}">${esc(rackName(id))}</button>`).join('')}</div>${rackWorkPositions(s,task)}${mapPerms().view?`<details class="operator-extra"><summary>Ver mapa de referencia</summary>${rackWorkMap(s,task)}</details>`:''}</div></details></div></details>${readOnly?'<div class="inventory-reopen-callout"><div><b>Conteo enviado a revisión</b><small>Reabre tu tarea si necesitas continuar.</small></div><button id="inventory-reopen-my-task" class="primary" type="button">Reabrir y continuar levantamiento</button></div>':loc?`<details class="operator-extra"><summary>Pallet y preparación de esta posición</summary>${selectedWorkPositionPanel(s)}</details>`:''}</section>`;
}
function resolveInventoryWorkCode(s,raw){
 const code=normalizarCodigoUbicacion(raw),assigned=assignedRackIds(s),racks=activeRacks(s.siteId);
 if(!code)return {error:'Escanea o escribe el código de la etiqueta.'};
 const locations=(store.data.locations||[]).filter(l=>l.siteId===s.siteId&&l.active!==false&&racks.some(r=>r.id===l.rackId));
 const matches=locations.filter(l=>[l.id,l.label,l.scanCode,codigoEscaneableUbicacion(l,store.data)].some(v=>v&&normalizarCodigoUbicacion(v)===code));
 if(matches.length>1)return {error:'La etiqueta coincide con varias posiciones. Elige la posición manualmente.'};
 if(matches.length){const loc=matches[0];return assigned.has(loc.rackId)?{location:loc,rackId:loc.rackId}:{error:'Esta posición no pertenece a tus racks asignados.'};}
 const rackMatches=racks.filter(r=>[r.id,r.rackCode,r.scanCode,r.name].some(v=>v&&normalizarCodigoUbicacion(v)===code));
 if(rackMatches.length>1)return {error:'Código de rack ambiguo. Elige tu rack manualmente.'};
 if(rackMatches.length){const r=rackMatches[0];return assigned.has(r.id)?{rackId:r.id}:{error:'Este rack no está asignado a tu tarea.'};}
 return {error:'Ubicación no reconocida en este centro. Revisa la etiqueta o elige manualmente.'};
}
function selectInventoryWorkCode(s){
 const input=document.querySelector('#inventory-work-code'),result=resolveInventoryWorkCode(s,input?.value);
 if(result.error){const status=document.querySelector('#inventory-work-status');if(status)status.textContent=result.error;input?.focus();return false;}
 inventoryWorkRackId=result.rackId;inventoryWorkLocationId=result.location?.id||'';inventoryWorkModule=result.location?locationModule(result.location):'';inventoryManualLocationOpen=!result.location;
 renderInventories(document.querySelector('#app'));
 if(result.location)setTimeout(()=>document.querySelector('#inventory-product-code')?.focus(),40);
 return true;
}
function inventoryOperatorWorkbench(s,task,{readOnly=false}={}){if(!task)return '';if(!inventoryWorkRackId||(task.rackIds||[]).includes(inventoryWorkRackId)===false)inventoryWorkRackId=(task.rackIds||[])[0]||'';if(inventoryWorkLocationId&&rackForLocation(inventoryWorkLocationId)!==inventoryWorkRackId)inventoryWorkLocationId='';if(operatorRole())return inventorySimpleWorkbench(s,task,readOnly);return `<section class="inventory-operator-workbench ${readOnly?'is-readonly':''}"><div class="inventory-operator-workbench-title"><div><span class="eyebrow">LEVANTAMIENTO POR RACK</span><h3>Levanta tu rack</h3><small>Rack → módulo → posición → pallet → producto.</small></div>${readOnly?'<span class="inventory-readonly-badge">EN REVISIÓN</span>':''}</div>${readOnly?'<div class="inventory-reopen-callout"><div><b>Este conteo fue enviado a revisión.</b><small>Puedes seguir viendo el rack y sus posiciones. Si necesitas continuar el levantamiento, reabre tu tarea.</small></div><button id="inventory-reopen-my-task" class="primary" type="button">Reabrir y continuar levantamiento</button></div>':''}${rackWorkMap(s,task)}${rackWorkPositions(s,task)}${readOnly?'':selectedWorkPositionPanel(s)}</section>`;}
function palletDialogHtml(){return `<dialog id="inventory-pallet-dialog" class="inventory-pallet-dialog"><section><div class="dialog-head"><div><span class="eyebrow">PALLET FÍSICO</span><h3>Crear pallet en esta posición</h3><small id="inventory-pallet-location-label"></small></div><button id="inventory-pallet-close" class="ghost" type="button">×</button></div><label>Identificador físico<div class="entrada-con-camara"><input id="inventory-pallet-code" placeholder="Ej. 001 o A12" autocomplete="off"><button class="numeric-keyboard-button" type="button" data-numeric-target="inventory-pallet-code" title="Teclado numérico">123</button><button id="inventory-pallet-code-scan" class="scan-button" type="button" title="Escanear identificador">▣</button></div><small>El sistema lo normaliza como PAL-001, PAL-A12, etc.</small></label><label>Nombre visible<div class="entrada-con-camara"><input id="inventory-pallet-name" placeholder="Ej. P-01" autocomplete="off"><button class="numeric-keyboard-button" type="button" data-numeric-target="inventory-pallet-name" title="Teclado numérico">123</button><button id="inventory-pallet-name-scan" class="scan-button" type="button" title="Escanear nombre o etiqueta">▣</button></div><small>Opcional. Puedes usar un nombre corto.</small></label><div class="dialog-actions"><button id="inventory-pallet-cancel" class="ghost" type="button">Cancelar</button><button id="inventory-pallet-save" class="primary" type="button">Crear y colocar aquí</button></div></section></dialog>`;}

function accessDenied(){return `<section class="panel">${empty('Inventarios no autorizado','Tu administrador debe habilitar el permiso de conteo de inventario para este centro.')}</section>`;}
function metricsHtml(list){const open=list.filter(s=>s.status==='EN_CONTEO').length,review=list.filter(s=>s.status==='EN_REVISION').length,lines=list.reduce((n,s)=>n+(s.lines||[]).length,0);return `<div class="inventory-metrics"><div><small>EN CONTEO</small><b>${open}</b></div><div><small>EN REVISIÓN</small><b>${review}</b></div><div><small>LÍNEAS REGISTRADAS</small><b>${lines}</b></div></div>`;}
function sessionMode(s){return s.countMode||s.inventoryMode||(s.blind===false||s.inventoryType==='CONTROLADO'?'CONTROLADO':'CIEGO');}
function sessionPurpose(s){if(s.purpose)return s.purpose;if(s.inventoryType==='VERIFICACION')return 'RECONTEO';if(s.inventoryType==='CICLICO')return 'CICLICO';return 'GENERAL';}
function sessionRackIds(s){const all=activeRacks(s.siteId).map(r=>r.id);if((s.scope||'ALL_ACTIVE_RACKS')==='ALL_ACTIVE_RACKS')return all;const explicit=Array.isArray(s.rackIds)?s.rackIds:[];if(explicit.length)return explicit;return [...new Set((s.assignments||[]).flatMap(a=>a.rackIds||[]))];}
function reviewCorrectionPlacement(s,code){return s.reviewCorrectionPlacementsByProduct?.[String(code)]||null;}
function reviewPlacementByInput(s,value){const clean=String(value||'').trim().toUpperCase();if(!clean)return null;const allowed=new Set(sessionRackIds(s));const locations=(store.data.locations||[]).filter(l=>l.siteId===s.siteId&&l.active!==false&&allowed.has(l.rackId));const location=locations.find(l=>[l.id,l.scanCode,l.label].some(v=>String(v||'').trim().toUpperCase()===clean));if(location)return {locationId:location.id,palletId:null,rackId:location.rackId,label:location.label||location.scanCode||location.id};const pallet=(store.data.pallets||[]).find(p=>p.siteId===s.siteId&&[p.id,p.physicalCode,p.displayName].some(v=>String(v||'').trim().toUpperCase()===clean));if(!pallet)return null;const palletLocation=locations.find(l=>l.id===pallet.locationId);return palletLocation?{locationId:palletLocation.id,palletId:pallet.id,rackId:palletLocation.rackId,label:`${pallet.displayName||pallet.physicalCode||pallet.id} · ${palletLocation.label||palletLocation.id}`} : null;}
function hasPositiveCountedPosition(s,code){return (s.lines||[]).some(l=>String(l.productCode)===String(code)&&Number(l.qty||0)>0&&l.locationId)||!!reviewCorrectionPlacement(s,code);}
function sessionSummaryLabel(s){const scope=(s.scope||'ALL_ACTIVE_RACKS')==='SELECTED_RACKS'?`${sessionRackIds(s).length} rack(s) seleccionados`:(SCOPE_LABEL.ALL_ACTIVE_RACKS);return `${TYPE_LABEL[sessionMode(s)]||'Conteo'} · ${PURPOSE_LABEL[sessionPurpose(s)]||'Inventario'} · ${scope}`;}
function assignmentNames(s){const a=s.assignments||[];if(!a.length)return 'Sin asignaciones';return a.map(x=>`${userName(x.userId)} · ${(x.rackIds||[]).map(rackName).join(', ')}`).join(' · ');}
function sessionCard(s){const lines=s.lines||[],units=lines.reduce((n,l)=>n+Number(l.qty||0),0),mine=taskForUser(s),archived=!!s.managerArchivedAt,canArchive=perms().manage&&!isGlobalInventoryAdmin()&&['CERRADA','CONCILIADA'].includes(s.status)&&!archived,canRestore=isGlobalInventoryAdmin()&&archived,canDeleteFinal=canGlobalDeleteInventory(s),mineOperational=!!mine&&!['CERRADA','CONCILIADA'].includes(s.status),myRacks=mine?(mine.rackIds||[]).map(rackName).join(', '):'';if(operatorRole())return `<article class="inventory-session-card inventory-operator-task-card ${mineOperational?'inventory-task-card':''}" data-inventory-id="${esc(s.id)}"><div class="inventory-session-main"><div><span class="eyebrow">${esc(s.number||s.id)}</span><h3>${esc(s.name||'Levantamiento físico')}</h3><small class="inventory-my-rack-label">${esc(myRacks||'Rack asignado')}</small></div>${badge(STATUS_LABEL[s.status]||s.status,STATUS_TONE[s.status]||'neutral')}</div><button class="primary open-inventory-session inventory-operator-open" type="button" data-id="${esc(s.id)}">${mineOperational?'Entrar y contar':'Ver mi levantamiento'}</button></article>`;return `<article class="inventory-session-card ${mineOperational?'inventory-task-card':''} ${archived?'is-archived':''}" data-inventory-id="${esc(s.id)}"><div class="inventory-session-main"><div><span class="eyebrow">${esc(s.number||s.id)}</span><h3>${esc(s.name||'Conteo de inventario')}</h3><small>${esc(siteName(s.siteId))} · ${esc(sessionSummaryLabel(s))}</small>${mine?`<small class="inventory-my-rack-label">Tu levantamiento: ${esc(myRacks||'rack asignado')}</small>`:''}${archived?`<small class="inventory-archived-note">Archivado por ${esc(userName(s.managerArchivedBy))} · ${esc(fecha(s.managerArchivedAt))}</small>`:''}</div>${badge(STATUS_LABEL[s.status]||s.status,STATUS_TONE[s.status]||'neutral')}</div><div class="inventory-session-stats"><span><b>${lines.length}</b><small>líneas</small></span><span><b>${units}</b><small>unidades</small></span><span><b>${(s.assignments||[]).length}</b><small>tarea(s)</small></span></div><div class="inventory-assignment-summary"><small>${esc(assignmentNames(s))}</small></div><div class="inventory-session-foot"><small>Creado ${esc(fecha(s.createdAt))}${s.closedAt?` · Cerrado ${esc(fecha(s.closedAt))}`:''}</small><div class="inventory-session-actions"><button class="${mineOperational?'primary':'secondary'} open-inventory-session" type="button" data-id="${esc(s.id)}">${mineOperational?`Trabajar ${esc(myRacks||'mi rack')}`:'Ver detalle'}</button>${canArchive?`<button class="ghost archive-inventory-session" type="button" data-id="${esc(s.id)}">Archivar para administrador</button>`:''}${canRestore?`<button class="secondary restore-inventory-session" type="button" data-id="${esc(s.id)}">Restaurar a la vista</button>`:''}${canDeleteFinal?`<button class="danger-action delete-final-inventory-session" type="button" data-id="${esc(s.id)}">Eliminar inventario</button>`:''}</div></div></article>`;}
function rackAssignmentRows(existing={}){const users=authorizedCounters(),racks=activeRacks(),selectedSet=new Set(existing.selectedRackIds||racks.map(r=>r.id)),partial=existing.scope==='SELECTED_RACKS';const groups=new Map();for(const r of racks){const k=r.sectorId||'SIN-ZONA';if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r);}return [...groups.entries()].map(([sectorId,rows])=>`<section class="inventory-zone-group"><div class="inventory-zone-head"><div><b>${esc(sectorName(sectorId))}</b><small>${rows.length} rack(s)</small></div><div class="inventory-zone-tools"><button type="button" class="ghost inventory-zone-toggle" data-sector="${esc(sectorId)}" ${partial?'':'hidden'}>Seleccionar zona</button><div class="inventory-zone-bulk"><select class="inventory-zone-user" data-sector="${esc(sectorId)}"><option value="">Responsable para toda la zona…</option>${users.map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join('')}</select><button type="button" class="ghost inventory-zone-same" data-sector="${esc(sectorId)}">Aplicar a zona</button></div></div></div><div class="inventory-rack-assignment-grid">${rows.map(r=>{const locked=existing.lockedRacks?.has(r.id),selected=existing.byRack?.[r.id]||'',included=selectedSet.has(r.id);return `<label class="inventory-rack-assignment ${locked?'is-locked':''} ${included?'is-included':'is-excluded'}"><span><span class="inventory-rack-title"><input class="inventory-rack-include" type="checkbox" data-rack="${esc(r.id)}" data-sector="${esc(sectorId)}" ${included?'checked':''} ${(!partial||locked)?'disabled':''}><b>${esc(r.name||r.id)}</b></span><small>${esc(r.usage||'Rack activo')}</small></span><select class="inventory-rack-user" data-rack="${esc(r.id)}" data-sector="${esc(sectorId)}" ${locked||!included?'disabled':''}><option value="">Sin asignar</option>${users.map(u=>`<option value="${esc(u.id)}" ${u.id===selected?'selected':''}>${esc(u.name)}</option>`).join('')}</select>${locked?'<small class="locked-note">Ya tiene conteos y no puede quitarse del alcance ni reasignarse.</small>':''}</label>`;}).join('')}</div></section>`).join('');}
function inventoryHelp(){return `<details class="inventory-type-help" open><summary>¿Qué tipo de inventario necesito?</summary><div class="inventory-type-help-grid"><div><b>Conteo ciego</b><span>El operario cuenta sin ver el stock del WMS. Ideal para detectar diferencias reales.</span></div><div><b>Conteo asistido</b><span>El operario ve el stock esperado mientras cuenta. Útil para verificaciones rápidas.</span></div><div><b>Inventario general</b><span>Conteo planificado normal, de toda la bodega o de racks seleccionados.</span></div><div><b>Verificación / reconteo</b><span>Segundo conteo para confirmar una diferencia o revisar productos y ubicaciones específicas.</span></div><div><b>Inventario cíclico</b><span>Conteos parciales periódicos por racks o zonas sin detener toda la bodega.</span></div></div></details>`;}
function createDialog(){return `<dialog id="inventory-create-dialog" class="inventory-dialog inventory-assignment-dialog"><section class="inventory-dialog-card"><div class="dialog-head"><div><span class="eyebrow">NUEVO INVENTARIO</span><h3>Crear y asignar inventario</h3><small>Define cómo se contará, qué racks participan y quién ejecutará cada tarea.</small></div><div class="inventory-window-actions"><button id="inventory-create-size" class="ghost" type="button" title="Ampliar ventana" aria-label="Ampliar ventana">⛶</button><button id="inventory-create-close" class="ghost" type="button" title="Cerrar" aria-label="Cerrar">×</button></div></div>${inventoryHelp()}<div class="inventory-form-grid"><label>Nombre del inventario<input id="inventory-name" placeholder="Ej. Conteo racks 1 a 3" autocomplete="off"><small>Opcional. Se generará un número INV automático.</small></label><label>Tipo / modalidad de conteo<select id="inventory-profile"><option value="GENERAL:CIEGO">Inventario general · Conteo ciego</option><option value="GENERAL:CONTROLADO">Inventario general · Conteo asistido / controlado</option><option value="RECONTEO:CIEGO">Verificación / reconteo · Conteo ciego</option><option value="RECONTEO:CONTROLADO">Verificación / reconteo · Conteo asistido / controlado</option><option value="CICLICO:CIEGO">Inventario cíclico · Conteo ciego</option><option value="CICLICO:CONTROLADO">Inventario cíclico · Conteo asistido / controlado</option></select><small>Elige directamente el tipo de inventario y cómo verá el stock el operario.</small></label><label>Alcance<select id="inventory-scope"><option value="ALL_ACTIVE_RACKS">Toda la bodega</option><option value="SELECTED_RACKS">Racks / zonas seleccionados</option></select><small id="inventory-scope-help">Se incluirán todos los racks activos del centro.</small></label></div>${rackMapReference()}<div class="inventory-assignment-help"><b>Asignación por rack y zona</b><span id="inventory-assignment-help-text">Cada rack activo debe quedar con un responsable. Puedes usar una sola persona o repartir la bodega entre varias.</span></div><div id="inventory-rack-assignments">${rackAssignmentRows({scope:'ALL_ACTIVE_RACKS'})}</div><div id="inventory-unassigned-warning" class="inventory-unassigned-warning" hidden></div><div class="dialog-actions"><button id="inventory-create-cancel" class="ghost" type="button">Cancelar</button><button id="inventory-create-save" class="primary" type="button">Crear y asignar tareas</button></div></section></dialog>`;}
function editAssignmentsDialog(s){const byRack={},lockedRacks=new Set(),selectedRackIds=sessionRackIds(s);for(const a of s.assignments||[])for(const r of a.rackIds||[])byRack[r]=a.userId;for(const l of s.lines||[])if(l.rackId)lockedRacks.add(l.rackId);return `<dialog id="inventory-edit-assignments-dialog" class="inventory-dialog inventory-assignment-dialog"><section class="inventory-dialog-card"><div class="dialog-head"><div><span class="eyebrow">${esc(s.number)}</span><h3>Editar asignaciones</h3><small>Alcance: ${esc(SCOPE_LABEL[s.scope||'ALL_ACTIVE_RACKS'])}. Los racks con conteos quedan protegidos.</small></div><button id="inventory-edit-close" class="ghost" type="button">×</button></div>${rackMapReference()}<div id="inventory-edit-rack-assignments">${rackAssignmentRows({byRack,lockedRacks,selectedRackIds,scope:s.scope||'ALL_ACTIVE_RACKS'})}</div><div id="inventory-edit-unassigned-warning" class="inventory-unassigned-warning" hidden></div><div class="dialog-actions"><button id="inventory-edit-cancel" class="ghost" type="button">Cancelar</button><button id="inventory-edit-save" class="primary" type="button">Guardar asignaciones</button></div></section></dialog>`;}
