function inventoryResultSummary(rows){const stats=inventoryResultStats(rows);return `<div class="inventory-result-summary"><div><small>PRODUCTOS</small><b>${stats.products}</b></div><div><small>UNIDADES FÍSICAS</small><b>${stats.physical}</b></div><div><small>CON DIFERENCIA</small><b>${stats.differences}</b></div><div class="shortage"><small>FALTANTES</small><b>${stats.shortages}</b></div><div class="surplus"><small>SOBRANTES</small><b>${stats.surpluses}</b></div><div class="match"><small>COINCIDEN</small><b>${stats.matches}</b></div></div>`;}
