 document.querySelector('#inventory-found-name').value=(s.lines||[]).find(l=>l.foundWithoutCatalog&&normalizeProductCode(l.productCode)===code)?.productName||'';
 document.querySelector('#inventory-found-qty').value=document.querySelector('#inventory-count-qty')?.value||'';
