function unknownInventorySummary(s){const lines=(s.lines||[]).filter(l=>l.foundWithoutCatalog);if(!lines.length)return '';const codes=new Set(lines.map(l=>l.productCode));return `<details class="inventory-found-summary"><summary>Productos encontrados fuera del catálogo: ${codes.size} código(s) · ${lines.reduce((n,l)=>n+Number(l.qty||0),0)} unidades</summary><p>Hallazgos registrados durante este inventario. Antes de conciliar, da de alta los códigos pendientes en Productos usando el mismo código.</p>${lineRows({lines})}</details>`;}

function updateResolved(){const code=document.querySelector('#inventory-product-code')?.value||'',posText=document.querySelector('#inventory-location-code')?.value||'',p=resolveProduct(code,store.data),pos=resolvePosition(posText),s=sessions().find(x=>x.id===currentSessionId),allowed=s?assignedRackIds(s):new Set(),validPos=pos&&allowed.has(pos.rackId),box=document.querySelector('#inventory-resolved'),ps=document.querySelector('#inventory-product-status'),ls=document.querySelector('#inventory-location-status'),stock=physicalByProductAtSite();const add=document.querySelector('#inventory-add-unknown');if(add)add.hidden=!code.trim()||!!p;if(ps)ps.textContent=p?`${p.code} · ${p.name||p.description||'Producto'}${!operatorRole()&&sessionMode(s)==='CONTROLADO'?` · Stock sistema: ${Number(stock[p.code]||0)}`:''}`:code.trim()?'Este código no existe en el catálogo. Puedes registrar el producto encontrado.':'Escanea o escribe un código válido.';if(ls)ls.textContent=validPos?`${rackName(pos.rackId)} · ${pos.locationLabel}${pos.palletId?` · ${pos.palletLabel}`:''}`:pos?'Esta posición no pertenece a tus racks asignados.':'Debe pertenecer a uno de tus racks asignados.';if(box){box.hidden=operatorRole()?!p:!(p||pos);box.innerHTML=`${p?`<span><small>PRODUCTO</small><b>${esc(p.code)}</b><strong>${esc(p.name||p.description||'Producto')}</strong></span>`:''}${pos&&!operatorRole()?`<span class="${validPos?'':'invalid'}"><small>POSICIÓN CONTADA</small><b>${esc(rackName(pos.rackId)||'Sin rack')}</b><strong>${esc(pos.locationLabel)}</strong></span>`:''}`;}}
async function reopenMyInventoryTask(s){const task=taskForUser(s);if(!task||s.status!=='EN_REVISION'||taskStatus(s,task)!=='ENVIADO_REVISION')throw new Error('Esta tarea no está disponible para reabrir.');if(!perms().count)throw new Error('Tu usuario no tiene permiso para realizar conteos de inventario.');if(!confirm(`¿Reabrir tu levantamiento de ${s.number||s.id}?\n\nLa sesión volverá a EN CONTEO para que puedas seguir trabajando tus racks asignados.`))return;const at=new Date().toISOString();await store.commit(d=>{const target=(d.planning?.inventorySessions||[]).find(x=>x.id===s.id),a=target?.assignments?.find(x=>x.id===task.id);if(!target||target.status!=='EN_REVISION'||!a||a.status!=='ENVIADO_REVISION')throw new Error('El inventario cambió de estado y ya no puede reabrirse desde esta pantalla.');a.status='EN_CONTEO';delete a.submittedAt;delete a.submittedBy;target.status='EN_CONTEO';delete target.reviewReadyAt;delete target.systemSnapshotByProduct;delete target.systemSnapshotScope;target.updatedAt=at;},`Conteo ${s.number||s.id} reabierto por ${currentUser().name||currentUser().id}`,{operations:['inventoryCount']});await notice('Levantamiento reabierto','Ya puedes continuar por rack, posición y pallet.','success');renderInventories(document.querySelector('#app'));}
