async function toggleRackReviewed(s,rackId){const task=taskForUser(s);if(!task||!(task.rackIds||[]).includes(rackId))return;const done=new Set(task.completedRackIds||[]),mark=!done.has(rackId),at=new Date().toISOString();await store.commit(d=>{const target=(d.planning?.inventorySessions||[]).find(x=>x.id===s.id),a=target?.assignments?.find(x=>x.id===task.id);if(!a||a.status==='ENVIADO_REVISION')return;const set=new Set(a.completedRackIds||[]);if(mark)set.add(rackId);else set.delete(rackId);a.completedRackIds=[...set];a.status='EN_CONTEO';a.startedAt=a.startedAt||at;target.updatedAt=at;},`${s.number}: ${rackName(rackId)} ${mark?'marcado revisado':'reabierto para conteo'}`,{operations:['inventoryCount']});renderInventories(document.querySelector('#app'));}
