async function closeInventory(s){if(!perms().manage){await notice('Acceso insuficiente','Solo el jefe de bodega o un administrador autorizado puede cerrar el inventario.','warning');return;}if(!allTasksSubmitted(s)){toast('Todavía hay tareas de conteo pendientes.','warning');return;}if(!confirm(`¿Cerrar definitivamente el inventario ${s.number}? El conteo quedará congelado para la siguiente etapa de conciliación. Después de cerrar ya no se podrán corregir cantidades desde Inventarios.`))return;const at=new Date().toISOString(),u=currentUser();await store.commit(d=>{const target=(d.planning?.inventorySessions||[]).find(x=>x.id===s.id);if(!target||target.status!=='EN_REVISION')throw new Error('El inventario ya no está disponible para cerrar.');target.status='CERRADA';target.closedAt=at;target.closedBy=u.id;target.updatedAt=at;},`Inventario ${s.number} cerrado por ${u.name||u.id}`,{operations:['inventoryManage']});inventoryReviewEditEnabled=false;await notice('Inventario cerrado','El conteo quedó congelado. El siguiente paso será su conciliación; el stock todavía no fue modificado.','success');renderInventories(document.querySelector('#app'));}
